-- Current Natural Balance Platefulls web-label formulas and exact Chewy identity aliases.
-- Evidence: outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json
-- The current Chewy CDN package fronts are identity-only evidence. Historical
-- Chewy UPCs remain distinct and no retailer ingredient text is promoted.

DO $migration$
DECLARE
  v_aliases JSONB := convert_from(decode('', 'base64'), 'utf8')::jsonb;
  v_observations JSONB := convert_from(decode('', 'base64'), 'utf8')::jsonb;
  v_run JSONB := jsonb_build_object(
    'run_key', 'reconcile_natural_balance_platefulls_current_web_labels:manufacturer-observations',
    'source_slug', 'natural-balance',
    'source_type', 'manufacturer',
    'coverage_role', 'denominator',
    'status', 'completed',
    'started_at', NOW(),
    'finished_at', NOW(),
    'pagination_complete', TRUE,
    'truncated', FALSE,
    'cap_reached', FALSE,
    'observed_count', jsonb_array_length(v_observations),
    'metadata', jsonb_build_object(
      'audit_artifact', 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json',
      'bounded_exact_evidence', TRUE,
      'current_public_web_labels', TRUE
    )
  );
  v_alias JSONB;
  v_formula public.catalog_formulas%ROWTYPE;
  v_serving public.product_data%ROWTYPE;
  v_observation_id BIGINT;
  v_normalized_alias TEXT;
  v_top_cache TEXT;
  v_rows INTEGER;
BEGIN
  PERFORM public.stage_catalog_census_batch(v_run, v_observations);

  FOR v_alias IN SELECT value FROM jsonb_array_elements(v_aliases)
  LOOP
    UPDATE public.product_data
    SET flavor = v_alias#>>'{target_identity,flavor}',
        updated_at = NOW()
    WHERE cache_key = v_alias->>'cache_key'
      AND gtin = v_alias->>'current_package_gtin'
      AND brand = v_alias#>>'{target_identity,brand}'
      AND pet_type = v_alias#>>'{target_identity,pet_type}'
      AND COALESCE(life_stage, 'unknown') =
          COALESCE(v_alias#>>'{target_identity,life_stage}', 'unknown')
      AND COALESCE(food_form, 'unknown') =
          COALESCE(v_alias#>>'{target_identity,food_form}', 'unknown')
      AND source_url = v_alias->>'official_source_url'
      AND image_url = v_alias->>'official_database_image_url'
      AND ingredient_count = (v_alias->>'official_ingredient_count')::INTEGER
      AND encode(
        digest(public.catalog_normalize_ingredient_evidence(ingredient_text), 'sha256'),
        'hex'
      ) = v_alias->>'official_database_ingredient_hash'
      AND source_quality = 'manufacturer'
      AND ingredient_verification_status = 'label_ocr_verified'
      AND image_verification_status = 'manufacturer'
      AND formula_evidence_tier = 'web_label_version'
      AND formula_version_provenance->>'package_gtin' =
          v_alias->>'current_package_gtin'
      AND is_complete_food
      AND catalog_exclusion_reason IS NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Expected one protected serving correction for %, found %',
        v_alias->>'cache_key', v_rows;
    END IF;

    SELECT * INTO STRICT v_serving
    FROM public.product_data
    WHERE cache_key = v_alias->>'cache_key'
      AND flavor = v_alias#>>'{target_identity,flavor}'
      AND gtin = v_alias->>'current_package_gtin'
      AND source_url = v_alias->>'official_source_url'
      AND image_url = v_alias->>'official_database_image_url'
      AND ingredient_count = (v_alias->>'official_ingredient_count')::INTEGER
      AND encode(
        digest(public.catalog_normalize_ingredient_evidence(ingredient_text), 'sha256'),
        'hex'
      ) = v_alias->>'official_database_ingredient_hash'
      AND source_quality = 'manufacturer'
      AND ingredient_verification_status = 'label_ocr_verified'
      AND image_verification_status = 'manufacturer'
      AND formula_evidence_tier = 'web_label_version'
      AND is_complete_food
      AND catalog_exclusion_reason IS NULL;

    SELECT * INTO STRICT v_formula
    FROM public.catalog_formulas
    WHERE formula_key = v_alias->>'target_formula_key'
      AND source_url = v_alias->>'official_source_url'
      AND front_image_url = v_alias->>'official_database_image_url'
      AND cardinality(ingredients) = (v_alias->>'official_ingredient_count')::INTEGER
      AND encode(
        digest(public.catalog_normalize_ingredient_evidence(ingredient_text), 'sha256'),
        'hex'
      ) = v_alias->>'official_database_ingredient_hash'
      AND verification_status = 'verified'
      AND ingredient_verification_status = 'label_ocr_verified'
      AND image_verification_status = 'manufacturer'
      AND active;

    UPDATE public.catalog_formulas
    SET formula_version_provenance = COALESCE(formula_version_provenance, '{}'::JSONB)
          || jsonb_build_object(
            'package_gtin', v_alias->>'current_package_gtin',
            'package_size', v_alias#>>'{target_identity,package_size}',
            'ingredient_text_hash', v_alias->>'official_database_ingredient_hash',
            'version_evidence', 'current_manufacturer_web_label'
          ),
        updated_at = NOW()
    WHERE id = v_formula.id
      AND COALESCE(formula_version_provenance->>'package_gtin',
                   v_alias->>'current_package_gtin') =
          v_alias->>'current_package_gtin'
      AND v_alias->>'archived_package_gtin' <>
          v_alias->>'current_package_gtin';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Expected one protected formula provenance update for %, found %',
        v_alias->>'target_formula_key', v_rows;
    END IF;

    IF v_formula.promoted_cache_key IS NULL THEN
      PERFORM public.promote_catalog_formula(v_formula.id);
    END IF;

    SELECT * INTO STRICT v_formula
    FROM public.catalog_formulas
    WHERE id = v_formula.id
      AND formula_key = v_alias->>'target_formula_key'
      AND promoted_cache_key = v_serving.cache_key
      AND source_url = v_alias->>'official_source_url'
      AND formula_evidence_tier = 'web_label_version'
      AND formula_version_provenance->>'package_gtin' =
          v_alias->>'current_package_gtin'
      AND verification_status = 'verified'
      AND ingredient_verification_status = 'label_ocr_verified'
      AND image_verification_status = 'manufacturer'
      AND active;

    IF EXISTS (
      SELECT 1 FROM public.catalog_formula_aliases
      WHERE alias_formula_key = v_alias->>'alias_formula_key'
        AND formula_id <> v_formula.id
    ) THEN
      RAISE EXCEPTION 'Alias already belongs to another formula: %',
        v_alias->>'alias_formula_key';
    END IF;

    INSERT INTO public.catalog_formula_aliases (
      alias_formula_key,
      formula_id,
      identity_hash,
      match_reason,
      source_url,
      metadata,
      updated_at
    ) VALUES (
      v_alias->>'alias_formula_key',
      v_formula.id,
      v_formula.identity_hash,
      'manual_review',
      v_alias->>'source_url',
      jsonb_build_object(
        'reason', v_alias->>'review_reason',
        'review_method', v_alias->>'review_method',
        'reviewed_at', v_alias->>'reviewed_at',
        'retailer_identity_only', TRUE,
        'retailer_ingredient_verification', FALSE,
        'retailer_source_slug', v_alias->>'retailer_source_slug',
        'retailer_product_id', v_alias->>'retailer_product_id',
        'retailer_title', v_alias->>'retailer_title',
        'retailer_front_image_url', v_alias->>'retailer_front_image_url',
        'retailer_front_image_sha256', v_alias->>'retailer_front_image_sha256',
        'official_front_image_url', v_alias->>'official_front_image_url',
        'official_front_image_sha256', v_alias->>'official_front_image_sha256',
        'manual_package_image_match', TRUE,
        'manual_front_label_visual_match', TRUE,
        'protected_identity_terms', v_alias->'protected_identity_terms',
        'current_package_gtin', v_alias->>'current_package_gtin',
        'archived_package_gtin', v_alias->>'archived_package_gtin',
        'archive_version_relation', v_alias->>'archive_version_relation',
        'gtin_resolution_policy', v_alias->>'gtin_resolution_policy',
        'official_source_url', v_alias->>'official_source_url',
        'official_database_ingredient_hash',
          v_alias->>'official_database_ingredient_hash',
        'official_canonical_ingredient_hash',
          v_alias->>'official_canonical_ingredient_hash',
        'audit_artifact', 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json'
      ),
      NOW()
    )
    ON CONFLICT (alias_formula_key) DO UPDATE
    SET source_url = EXCLUDED.source_url,
        metadata = public.catalog_formula_aliases.metadata || EXCLUDED.metadata,
        updated_at = NOW()
    WHERE public.catalog_formula_aliases.formula_id = EXCLUDED.formula_id;

    SELECT observation.id INTO v_observation_id
    FROM public.catalog_observations observation
    WHERE observation.source_slug = v_alias->>'retailer_source_slug'
      AND observation.source_external_id = v_alias->>'retailer_product_id'
      AND lower(regexp_replace(observation.source_url, '/+$', '')) =
          lower(regexp_replace(v_alias->>'source_url', '/+$', ''))
    ORDER BY observation.observed_at DESC NULLS LAST, observation.id DESC
    LIMIT 1;
    IF v_observation_id IS NULL THEN
      RAISE EXCEPTION 'Retailer observation missing for %',
        v_alias->>'retailer_product_id';
    END IF;

    INSERT INTO public.catalog_field_evidence (
      formula_id,
      observation_id,
      field_name,
      field_value,
      source_url,
      source_authority,
      accepted,
      observed_at,
      content_hash
    ) VALUES (
      v_formula.id,
      v_observation_id,
      'retailer_exact_identity_alias',
      jsonb_build_object(
        'alias_formula_key', v_alias->>'alias_formula_key',
        'review_method', v_alias->>'review_method',
        'retailer_identity_only', TRUE,
        'retailer_ingredient_verification', FALSE,
        'retailer_front_image_sha256', v_alias->>'retailer_front_image_sha256',
        'official_front_image_sha256', v_alias->>'official_front_image_sha256',
        'current_package_gtin', v_alias->>'current_package_gtin',
        'archived_package_gtin', v_alias->>'archived_package_gtin',
        'gtin_resolution_policy', v_alias->>'gtin_resolution_policy',
        'audit_artifact', 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json'
      ),
      v_alias->>'source_url',
      'retailer_identity',
      TRUE,
      (v_alias->>'retailer_observed_at')::TIMESTAMPTZ,
      encode(digest(
        v_formula.id::TEXT || '|retailer_exact_identity_alias|' ||
        (v_alias->>'alias_formula_key') || '|' ||
        (v_alias->>'retailer_front_image_sha256') || '|' ||
        (v_alias->>'official_database_ingredient_hash'),
        'sha256'
      ), 'hex')
    )
    ON CONFLICT (formula_id, field_name, source_url, content_hash) DO UPDATE
    SET observation_id = EXCLUDED.observation_id,
        field_value = EXCLUDED.field_value,
        source_authority = EXCLUDED.source_authority,
        accepted = TRUE,
        observed_at = EXCLUDED.observed_at;

    v_normalized_alias := public.normalize_verified_product_search_query(
      v_alias->>'retailer_title'
    );
    IF EXISTS (
      SELECT 1 FROM public.catalog_verified_product_search_aliases
      WHERE active
        AND normalized_alias = v_normalized_alias
        AND cache_key <> v_serving.cache_key
    ) THEN
      RAISE EXCEPTION 'Search alias belongs to another product: %',
        v_alias->>'retailer_title';
    END IF;

    INSERT INTO public.catalog_verified_product_search_aliases (
      cache_key,
      alias_text,
      normalized_alias,
      source_url,
      source_authority,
      evidence_observed_at,
      provenance,
      active,
      updated_at
    ) VALUES (
      v_serving.cache_key,
      v_alias->>'retailer_title',
      v_normalized_alias,
      v_alias->>'source_url',
      'retailer_identity',
      (v_alias->>'retailer_observed_at')::TIMESTAMPTZ,
      jsonb_build_object(
        'review_method', v_alias->>'review_method',
        'retailer_identity_only', TRUE,
        'retailer_ingredient_verification', FALSE,
        'formula_id', v_formula.id,
        'official_source_url', v_alias->>'official_source_url',
        'audit_artifact', 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json'
      ),
      TRUE,
      NOW()
    )
    ON CONFLICT (normalized_alias) WHERE active DO UPDATE
    SET cache_key = EXCLUDED.cache_key,
        alias_text = EXCLUDED.alias_text,
        source_url = EXCLUDED.source_url,
        source_authority = EXCLUDED.source_authority,
        evidence_observed_at = EXCLUDED.evidence_observed_at,
        provenance = public.catalog_verified_product_search_aliases.provenance
          || EXCLUDED.provenance,
        updated_at = NOW()
    WHERE public.catalog_verified_product_search_aliases.cache_key =
      EXCLUDED.cache_key;

    SELECT result.cache_key INTO v_top_cache
    FROM public.search_verified_products(v_alias->>'retailer_title', 8) result
    ORDER BY result.rank DESC
    LIMIT 1;
    IF v_top_cache IS DISTINCT FROM v_serving.cache_key THEN
      RAISE EXCEPTION 'Exact-title search regression for %: expected %, got %',
        v_alias->>'retailer_product_id', v_serving.cache_key, v_top_cache;
    END IF;
  END LOOP;

  IF (SELECT count(*) FROM public.catalog_formula_aliases
      WHERE metadata->>'audit_artifact' = 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json') <>
      jsonb_array_length(v_aliases)
     OR (SELECT count(*) FROM public.catalog_field_evidence
         WHERE accepted
           AND field_name = 'retailer_exact_identity_alias'
           AND field_value->>'audit_artifact' = 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json') <>
           jsonb_array_length(v_aliases)
     OR (SELECT count(*) FROM public.catalog_verified_product_search_aliases
         WHERE active
           AND provenance->>'audit_artifact' = 'outputs/catalog-deterministic-reconciliation-batches/20260809-natural-balance-platefulls-visual/report.json') <>
           jsonb_array_length(v_aliases) THEN
    RAISE EXCEPTION 'Natural Balance Platefulls postcondition failed';
  END IF;
END
$migration$;
